// Node: "Merge AI result"  (Code node, run once for all items)
// Parses and validates the classifier's JSON, then combines it with the
// validated ticket. The AI returns only 4 fields: intent, confidence,
// order_id and summary. Tone and urgency are not used anywhere.
//
// If the LLM call failed (rate limit, timeout, invalid JSON), the ticket
// still goes through, marked ai_failed, and the routing step sends it to a
// person. No guessing.
//
// Why parse here instead of n8n's Structured Output Parser node? That node
// requires the model to wrap its answer in an extra {"output": ...} key, and
// smaller models sometimes skip it. JSON mode + validation in code works
// the same with OpenAI, Groq, Gemini or a local model.

const INTENTS = ['wismo', 'cancel_request', 'return_exchange', 'refund_status',
  'damaged_or_wrong_item', 'payment_issue', 'product_query', 'complaint', 'other'];
const ORDER_ID_RE = /\bORD[-\s]?(\d{4,})\b/i;

const normaliseOrderId = (text) => {
  const m = String(text ?? '').match(ORDER_ID_RE);
  return m ? `ORD-${m[1]}` : null;
};

function parseModelJson(text) {
  if (typeof text !== 'string') return null;
  const cleaned = text.trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '');
  try {
    const parsed = JSON.parse(cleaned);
    // Accept {"output": {...}} too, in case a model wraps its answer.
    const obj = parsed && typeof parsed.output === 'object' ? parsed.output : parsed;
    return obj && typeof obj === 'object' && !Array.isArray(obj) ? obj : null;
  } catch {
    return null;
  }
}

// One webhook call = one ticket = one item, so .first() is safe here.
const item = $input.first();
const base = $('Validate & normalise').first().json;
{
  // In JSON mode the chain node usually parses the JSON itself and returns
  // the fields directly; otherwise it returns the raw string in "text".
  const raw = item.json;
  const ai = raw.error ? null
    : typeof raw.text === 'string' ? parseModelJson(raw.text)
    : raw.output && typeof raw.output === 'object' ? raw.output
    : raw;
  const aiFailed = !ai || !INTENTS.includes(ai.intent);

  // Prefer the ID the model found, but fall back to a regex on the raw
  // message: a deterministic check is cheaper and never hallucinates.
  const orderId = normaliseOrderId(ai?.order_id) ?? normaliseOrderId(base.ticket.message);

  const confidence = Number(ai?.confidence);
  return [{
    json: {
      ...base,
      ai: {
        failed: aiFailed,
        error: aiFailed ? String(raw.error ?? 'Model did not return valid JSON').slice(0, 300) : null,
        intent: aiFailed ? 'other' : ai.intent,
        confidence: aiFailed ? 0 : (Number.isFinite(confidence) ? Math.min(1, Math.max(0, confidence)) : 0),
        summary: aiFailed ? null : String(ai.summary ?? '').slice(0, 300),
        order_id: orderId,
        // Not used for routing or shown in the UI. Fixed values only because
        // the tickets table still has these columns.
        sentiment: 'neutral',
        urgency: 'medium',
      },
    },
  }];
}

// Node: "Routing rules"  (Code node, run once for all items)
//
// The AI only labels the message (intent, order ID, confidence). Everything
// here is plain code that reads live order data:
//
//   score = intent base + fact adjustment   (+ problem, - everything on track)
//   score below AUTO_LINE  -> automatic template reply, never in the queue
//   score AUTO_LINE or more -> a person, queue sorted by score, then oldest
//
// Tone is not used. Change a number in CONFIG, not in the rules below.

// ---------------- CONFIG: every score lives here ----------------
const AUTO_LINE = 25;

const BASE = {
  refund: 60,          // the customer's own money
  damaged: 55,         // paid, product broken, needs a decision
  cancel: 45,          // can cost shipping both ways if missed
  wismo: 15,           // information
  question: 10,        // product question / other
  anything_else: 30,   // return, complaint, payment, AI unavailable...
};

const ADJUST = {
  refund_late: +20,               // 80: expected date passed, or never started
  refund_on_schedule: -45,        // 15: expected date not passed yet
  refund_waiting_for_rto: -45,    // 15: parcel still on its way back
  cancel_not_shipped: +30,        // 75: window closes within hours
  cancel_shipped_cod: -30,        // 15: refuse the parcel, nothing paid
  cancel_cannot_stop: 0,          // 45: shipped prepaid or delivered
  wismo_delivered_not_received: +25, // 40: possible lost parcel
  wismo_late: +15,                // 30: past expected delivery date
  wismo_on_time: -5,              // 10
};

const FIXED = {
  no_matching_order: 5,  // order ID + email don't match: ask for their own
  too_vague: 5,          // AI confidence below MIN_CONFIDENCE
};

const MIN_CONFIDENCE = 0.7;
// ----------------------------------------------------------------

const today = new Date(Date.now() + 330 * 60_000).toISOString().slice(0, 10); // India date

function toPriority(score) {
  if (score >= 70) return 1;
  if (score >= 55) return 2;
  if (score >= 40) return 3;
  if (score >= 25) return 4;
  return 5;
}

// Each rule returns { base, adjust, label, reply }.
// reply = the template key used when the score is below AUTO_LINE.
const rule = (base, adjust, label, reply = null) => ({ base, adjust, label, reply });
const fixed = (score, label, reply) => ({ fixedScore: score, label, reply });

function decide(ai, order) {
  if (ai.failed) return rule('anything_else', null, 'AI unavailable: a person reads it');
  if (ai.confidence < MIN_CONFIDENCE) return fixed(FIXED.too_vague, 'Message too vague: asked for details', 'ask_details');

  if (ai.intent === 'product_query' || ai.intent === 'other') {
    return rule('question', null, 'Question we cannot answer from data yet: sent FAQ link', 'faq');
  }

  const orderIntents = ['wismo', 'cancel_request', 'refund_status', 'damaged_or_wrong_item'];
  if (orderIntents.includes(ai.intent) && !order) {
    return fixed(FIXED.no_matching_order, 'No order matches this email: asked for their own order ID', 'ask_order_id');
  }

  switch (ai.intent) {
    case 'wismo': {
      if (order.status === 'delivered') return rule('wismo', 'wismo_delivered_not_received', 'Marked delivered but customer says not received');
      if (['cancelled', 'rto_initiated', 'returned'].includes(order.status)) {
        return rule('anything_else', null, `Order is ${order.status.replace('_', ' ')}: a person explains`);
      }
      if (order.expected_on && order.expected_on < today) return rule('wismo', 'wismo_late', 'Past expected delivery date: chase the courier');
      return rule('wismo', 'wismo_on_time', 'On time: sent status from order data', 'wismo_on_time');
    }

    case 'cancel_request': {
      // Step 1: has it shipped?  Step 2: COD or prepaid?
      if (['placed', 'packed'].includes(order.status)) return rule('cancel', 'cancel_not_shipped', 'Not shipped yet: cancel before dispatch');
      if (['shipped', 'out_for_delivery'].includes(order.status)) {
        if (order.payment_method === 'cod') return rule('cancel', 'cancel_shipped_cod', 'Shipped COD: told to refuse the parcel', 'cancel_shipped_cod');
        return rule('cancel', 'cancel_cannot_stop', 'Shipped prepaid: refuse delivery, refund after it returns');
      }
      if (order.status === 'delivered') return rule('cancel', 'cancel_cannot_stop', 'Already delivered: handle as a return');
      return rule('anything_else', null, `Order is ${order.status.replace('_', ' ')}: a person checks`);
    }

    case 'refund_status': {
      // Step 1: has a refund started?  Step 2: is the expected date passed?
      if (order.refund_status === 'initiated') {
        if (order.refund_due_on && order.refund_due_on >= today) {
          return rule('refund', 'refund_on_schedule', `Refund on schedule, due ${order.refund_due_on}`, 'refund_on_schedule');
        }
        return rule('refund', 'refund_late', `Refund past its expected date (${order.refund_due_on})`);
      }
      if (order.status === 'rto_initiated') {
        return rule('refund', 'refund_waiting_for_rto', 'Parcel still coming back: refund starts when it arrives', 'refund_waiting_for_rto');
      }
      const owed = order.status === 'returned' || (order.status === 'cancelled' && order.payment_method === 'prepaid');
      if (owed) return rule('refund', 'refund_late', 'Refund never started');
      return rule('anything_else', null, 'Refund question with no refund due: a person checks');
    }

    case 'damaged_or_wrong_item':
      return rule('damaged', null, 'Damaged or wrong item: a person approves replacement or refund');

    default: // return_exchange, complaint, payment_issue
      return rule('anything_else', null, `${ai.intent.replaceAll('_', ' ')}: a person handles it`);
  }
}

const item = $input.first();
const base = $('Merge AI result').first().json;
{
  // "Lookup order" emits an empty item when nothing matched (Always Output Data).
  const order = item.json.order_id ? item.json : null;
  const r = decide(base.ai, order);

  let score, breakdown;
  if (r.fixedScore !== undefined) {
    score = r.fixedScore;
    breakdown = `fixed ${score}`;
  } else {
    const b = BASE[r.base];
    const a = r.adjust ? ADJUST[r.adjust] : 0;
    score = Math.max(0, Math.min(100, b + a));
    breakdown = `${r.base} ${b}` + (r.adjust ? ` ${a >= 0 ? '+' : '-'} ${r.adjust} ${Math.abs(a)}` : '');
  }

  // Auto only if the score is below the line AND we have a template for it.
  const auto = score < AUTO_LINE && Boolean(r.reply);

  const decision = {
    status: auto ? 'auto_resolved' : 'needs_human',
    reply_mode: auto ? r.reply : null,
    priority_score: score,
    priority: toPriority(score),
    reason: `${r.label}. Score ${score} = ${breakdown}`,
  };
  return [{ json: { ...base, order, decision } }];
}

// Node: "Build ticket row"  (Code node, run once for all items)
// Fills the reply template for automatic tickets and shapes the exact row
// the database expects. No AI here: templates are filled only from order
// data, so the reply never invents a date or promises anything.
// Tickets for a person get no draft; the agent writes the reply.

// Replace with the brand's real FAQ page.
const FAQ_URL = 'https://example.com/faq';

const fmtDate = (d) => (d
  ? new Date(`${String(d).slice(0, 10)}T00:00:00+05:30`)
      .toLocaleDateString('en-IN', { day: 'numeric', month: 'short', timeZone: 'Asia/Kolkata' })
  : null);
const rupees = (n) => `₹${Number(n).toLocaleString('en-IN')}`;

function templateReply(mode, t, order) {
  const name = (t.customer_name ?? order?.customer_name ?? '').split(' ')[0] || 'there';
  const sign = `\n\nTeam ${order?.brand ?? 'Support'}`;
  const o = order;

  const T = {
    wismo_on_time: () => `Hi ${name}, your order ${o.order_id} is ${o.status.replaceAll('_', ' ')}` +
      (o.courier ? ` with ${o.courier} (tracking number ${o.awb})` : '') +
      (o.expected_on ? ` and is expected by ${fmtDate(o.expected_on)}` : '') + '.',
    cancel_shipped_cod: () => `Hi ${name}, your order ${o.order_id} has already shipped, so it can't be cancelled now. ` +
      'As it is Cash on Delivery, please refuse the parcel when it arrives. You will not be charged anything.',
    refund_on_schedule: () => `Hi ${name}, your refund` +
      (o.refund_amount ? ` of ${rupees(o.refund_amount)}` : '') +
      ` for order ${o.order_id} has been started and should reach you by ${fmtDate(o.refund_due_on)}.`,
    refund_waiting_for_rto: () => `Hi ${name}, your order ${o.order_id} is on its way back to our warehouse. ` +
      'Your refund will start as soon as it arrives, and we will confirm it with you.',
    faq: () => `Hi ${name}, thanks for your message! You'll find product details, ingredients and delivery areas at ${FAQ_URL}`,
    ask_details: () => `Hi ${name}, could you tell us a bit more about what you need help with? ` +
      'If it is about an order, please share your order ID (it looks like ORD-12345).',
    ask_order_id: () => `Hi ${name}, we couldn't find that order linked to this email. ` +
      'Could you share the order ID from your confirmation message (it looks like ORD-12345)?',
  };
  return T[mode] ? T[mode]() + sign : null;
}

// Keep in sync with the model set on the "Model: classifier" node.
const MODEL_NAME = 'llama-3.3-70b-versatile';

const ctx = $input.first().json;
{
  const { ticket: t, ai, order, decision } = ctx;

  let status = decision.status;
  let reason = decision.reason;
  const draft = status === 'auto_resolved' ? templateReply(decision.reply_mode, t, order) : null;

  // Never auto-resolve without a reply.
  if (status === 'auto_resolved' && !draft) {
    status = 'needs_human';
    reason = `Reply template missing: routed to a person. ${reason}`;
  }

  return [{
    json: {
      row: {
        external_id: t.external_id,
        channel: t.channel,
        customer_email: t.customer_email,
        customer_name: t.customer_name ?? order?.customer_name ?? null,
        subject: t.subject,
        message: t.message,
        received_at: t.received_at,
        intent: ai.intent,
        sentiment: ai.sentiment,
        urgency: ai.urgency,
        confidence: Number(ai.confidence.toFixed(2)),
        extracted_order_id: ai.order_id,
        ai_summary: ai.summary,
        order_id: order?.order_id ?? null,
        status,
        priority: decision.priority,
        priority_score: decision.priority_score,
        routing_reason: reason,
        draft_reply: draft,
        processing_ms: Date.now() - ctx.started_at,
        model: MODEL_NAME,
        ai_failed: ai.failed,
      },
    },
  }];
}

parameters.responseBody:
={{ (() => {
  const r = $('Build ticket row').first().json.row;
  const saved = Boolean($json.id);
  return JSON.stringify({
    ok: true,
    ticket_id: saved ? $json.id : null,
    duplicate: !saved,
    status: r.status,
    intent: r.intent,
    sentiment: r.sentiment,
    priority: r.priority,
    priority_score: r.priority_score,
    routing_reason: r.routing_reason,
    order_id: r.order_id,
    reply: r.status === 'auto_resolved' ? r.draft_reply : null,
    processing_ms: r.processing_ms
  });
})() }}
